<?php require 'includes/functions.php'; if(is_logged_in())redirect('/movie-booking/index.php'); if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$name=trim($_POST['name']);$email=filter_var($_POST['email'],FILTER_VALIDATE_EMAIL);$pass=$_POST['password'];if(!$name||!$email||strlen($pass)<8)flash('error','Use a valid email and password of at least 8 characters.');else try{$s=db()->prepare('INSERT INTO users(name,email,password,phone) VALUES(?,?,?,?)');$s->execute([$name,$email,password_hash($pass,PASSWORD_DEFAULT),trim($_POST['phone'])]);flash('success','Account created. Please sign in.');redirect('/movie-booking/login.php');}catch(PDOException $e){flash('error','That email is already registered.');}} $pageTitle='Create account';require 'includes/header.php';?>
<div class="container py-5 col-md-6 col-lg-5"><div class="booking-panel"><h2>Join CineVerse</h2><form method="post" class="row g-3"><input type="hidden" name="csrf" value="<?=csrf()?>"><div class="col-12"><label class="form-label">Name</label><input required name="name" class="form-control"></div><div class="col-md-7"><label class="form-label">Email</label><input required type="email" name="email" class="form-control"></div><div class="col-md-5"><label class="form-label">Phone</label><input name="phone" class="form-control"></div><div class="col-12"><label class="form-label">Password</label><input required minlength="8" type="password" name="password" class="form-control"></div><div class="col-12"><button class="btn btn-gradient w-100">Create account</button></div></form><p class="mt-3 mb-0 text-secondary">Already a member? <a href="login.php">Sign in</a></p></div></div><?php require 'includes/footer.php'; ?>
